import { render } from "@solidjs/web";
import { MountGuarded } from "./App";

// The default entry with one change: it renders the component by name. The default reads App.tsx as a namespace, and a
// namespace the checker cannot list withholds ADR 0335's premise for the router. The pass over every element is the
// default's: its click on a route's link is the navigation to that route.
const root = document.getElementById("root")!;
const section = document.createElement("section");
section.dataset.export = "MountGuarded";
root.append(section);
try {
  render(() => <MountGuarded />, section);
} catch (error) {
  console.error("render failed", "MountGuarded", error);
  setTimeout(() => { throw error; });
}
const events: Array<[string, (type: string) => Event]> = [
  ...["click", "dblclick", "mousedown", "mouseup", "mouseover", "mouseout", "pointerdown", "pointerup", "contextmenu"]
    .map((type): [string, (type: string) => Event] => [type, (t) => new MouseEvent(t, { bubbles: true, cancelable: true })]),
];
const pause = (ms: number) => new Promise((done) => setTimeout(done, ms));
async function exercise() {
  await pause(200);
  for (let pass = 0; pass < 2; pass += 1) {
    for (const element of Array.from(root.querySelectorAll("*"))) {
      for (const [type, make] of events) {
        try {
          element.dispatchEvent(make(type));
        } catch (error) {
          console.error("handler threw", type, error);
        }
      }
    }
    await pause(200);
  }
  await pause(400);
  document.getElementById("ready")!.textContent = "settled";
}
void exercise();
